        {"id":"chat_clear_workspace", "areas":["chat"], "screen":"Основной чат /", "entry":"Основной чат.", "position":"В верхней панели, ближе к центру; значок метлы.", "control":"Кнопка очистки рабочего поля.", "does":"Убирает сообщения из текущего видимого состояния страницы.", "how_to_use":["Нажмите значок метлы в верхней панели.", "Учитывайте, что это очистка отображаемой переписки на экране."], "result":"Текущая область чата становится пустой.", "availability":"Если кнопка отображается в верхней панели.", "limits":"Не удаляет сохранённую историю из базы данных и не является удалением аккаунта. Для старых диалогов используйте /history."},
        {"id":"chat_open_profile", "areas":["chat","settings"], "screen":"Основной чат → Настройки /settings", "entry":"Основной чат /.", "position":"Верхняя панель, правый край — значок профиля/пользователя.", "control":"Profile / кнопка пользователя.", "does":"Открывает страницу профиля и настроек; если пользователь не вошёл, открывает модальное окно авторизации.", "how_to_use":["Нажмите значок профиля вверху справа.", "Если появилось окно входа, войдите через Google.", "После авторизации откроется /settings."], "result":"Появляется личный кабинет.", "availability":"На верхней панели.", "limits":"Не путайте профиль с кнопкой очистки чата в верхней панели."},
        {"id":"logo_help_center", "areas":["chat","guide","help-center","how-to-use"], "screen":"Основной чат → Help & Information /aprill", "entry":"Основной чат /.", "position":"Логотип APRIL вверху слева.", "control":"Логотип APRIL.", "does":"Открывает справочную страницу Help & Information, а не новый чат.", "how_to_use":["Нажмите логотип APRIL.", "На /aprill выберите нужную карточку справки.", "Чтобы вернуться к диалогу, откройте /."], "result":"Переход на страницу справки.", "availability":"Навигационная ссылка в верхней панели.", "limits":"Карточки статьи могут открываться на той же странице через выбор/якорь, а не иметь отдельный URL."},
        {"id":"response_feedback", "areas":["chat","response-feedback"], "screen":"Основной чат /", "entry":"Откройте основной чат и найдите конкретный ответ April.", "position":"Непосредственно под содержимым выбранного ответа — после текста и всех его render-блоков; на узком экране строка может переноситься.", "control":"«Жалоба» (Report) и «Спасибо» (Thanks). Рядом находится отдельная зелёная круглая стрелка «Опубликовать в сообществе». ", "does":"«Спасибо» только показывает локальное подтверждение «Спасибо за обратную связь.» примерно на 2,2 секунды и не отправляет отдельную оценку на сервер. «Жалоба» раскрывает форму выбора причины и отправляет обращение через POST /api/content-report.", "how_to_use":["Прокрутите именно к тому ответу, по которому хотите выполнить действие.", "Нажмите «Спасибо»: под кнопками на короткое время появится подтверждение; дополнительных шагов нет.", "Нажмите «Жалоба»: раскроется форма с вопросом о причине и списком вариантов — вредный/опасный, оскорбительный, вводящий в заблуждение или другая проблема.", "Выберите причину и нажмите «Отправить жалобу». Чтобы отказаться, нажмите «Отмена».", "Дождитесь сообщения об успешной отправке либо ошибки. Для технического обращения о работе сайта используйте Contact Support отдельно."], "result":"«Спасибо» показывает временный локальный toast; «Жалоба» после успешного ответа сервера показывает «Жалоба отправлена. Спасибо.»; при сбое — сообщение об ошибке.", "availability":"Компонент ReportAIResponse отрисовывается под каждым сообщением assistant в RenderMessage.tsx; в этом месте исходника нет проверки тарифа Free/Premium.", "limits":"Кнопка «Спасибо» не сохраняет рейтинг и не делает сетевой запрос в компоненте. Жалоба отправляет messageId, выбранную причину и короткий фрагмент ответа (до 2 000 символов); это не публичный пост и не отдельная форма Contact Support."},
        {"id":"assistant_response_share", "areas":["chat","response-feedback","space"], "screen":"Основной чат → Community /space", "entry":"Найдите ответ April, который хотите опубликовать, в основном чате /.", "position":"В строке действий непосредственно под конкретным ответом, рядом с «Жалоба» и «Спасибо»; зелёная круглая кнопка со стрелкой вверх.", "control":"aria-label/title: «Опубликовать в сообществе»; после успешной отправки: «Сообщение отправлено в сообщество.»", "does":"Одним нажатием отправляет текст текущего ответа April и поддерживаемый материал ответа (если он есть и доступен для публикации) в общую ленту через POST /api/community с action=send_message.", "how_to_use":["Откройте основной чат / и найдите нужный ответ April.", "Проверьте текст и прикреплённые материалы: нажатие публикует содержимое в Community, поэтому не размещайте секреты и личные данные.", "Нажмите зелёную круглую стрелку вверх под этим ответом. Не путайте её с отдельной стрелкой отправки в нижней панели чата или Community.", "Дождитесь подтверждения «Сообщение отправлено в сообщество.»; при ошибке появится сообщение о неудачной отправке."], "result":"Текущий ответ появляется как публикация в общей ленте April Community (/space); ручное копирование в поле Community для этого сценария не требуется.", "availability":"Контрол отрисовывается под ответом в основном чате; в коде компонента нет отдельного условия Premium для самой кнопки. Для публикации требуется доступ к авторизованному Community API.", "limits":"Текст отправляется с ограничением 3 800 символов. Для вложения используется первый переданный публикационный материал; после преобразования размер должен быть не более 3 MiB. Приватный/непубликуемый материал блокирует небезопасный переход к публикации одного только текста. Успех подтверждается сообщением UI; это не гарантирует, что пользователь открыл ленту."},
        {"id":"rendered_artifact_menu", "areas":["chat","image-controls"], "screen":"Основной чат / — карточка render-блока", "entry":"Откройте ответ с нужным артефактом.", "position":"Кнопка меню действий в верхней правой части карточки/панели соответствующего блока; визуальное положение зависит от renderer.", "control":"Open content actions menu / меню действий с материалом.", "does":"Открывает доступные операции над готовым блоком: Download, Share и/или Copy.", "how_to_use":["Найдите именно тот блок, который нужно сохранить или передать.", "Нажмите меню действий в его правом верхнем углу.", "Выберите доступное действие: Download сохраняет файл; Share вызывает системный Web Share, если браузер поддерживает, иначе для текстовых блоков возможна копия в буфер; Copy копирует содержимое, если обработчик предусмотрен."], "result":"Действие применяется к выбранному существующему результату.", "availability":"Зависит от типа блока и набора обработчиков у renderer.", "limits":"Нельзя обещать одновременное наличие всех пунктов у каждого типа артефакта. Если Share не поддержан, используйте Download или Copy, если они отображаются."},
        {"id":"settings_display_name", "areas":["settings"], "screen":"Настройки и профиль /settings", "entry":"Основной чат → значок профиля сверху справа.", "position":"Секция USER в профиле; поле имени и кнопка Edit/Save.", "control":"Edit → поле имени → Save.", "does":"Меняет отображаемое имя пользователя в профиле/сообществах.", "how_to_use":["Откройте /settings.", "В секции USER нажмите Edit.", "Измените имя и нажмите Save.", "Проверьте обновлённое значение после сохранения."], "result":"Новое имя становится отображаемым именем пользователя.", "availability":"После авторизации.", "limits":"Не является заменой April ID или Google-аккаунта."},
        {"id":"settings_copy_ids", "areas":["settings"], "screen":"Настройки и профиль /settings", "entry":"Основной чат → Profile.", "position":"В верхней части профиля рядом с идентификаторами аккаунта.", "control":"April ID / Premium ID и кнопка Copy.", "does":"Копирует соответствующий идентификатор в буфер обмена.", "how_to_use":["Откройте /settings.", "Найдите строку April ID или Premium ID.", "Нажмите Copy рядом с нужным ID.", "Вставьте его в безопасное место/форму, если это действительно требуется."], "result":"Идентификатор копируется; секреты или пароль кнопка не показывает.", "availability":"April ID для вошедшего пользователя; Premium ID — при наличии Premium.", "limits":"ID — идентификатор, не пароль. Не публикуйте его без необходимости."},
        {"id":"settings_language", "areas":["settings"], "screen":"Настройки и профиль /settings", "entry":"Основной чат → Profile.", "position":"Отдельная языковая секция ниже карточки профиля и текущего тарифа.", "control":"Кнопки языка и More languages.", "does":"Меняет язык интерфейса/предпочтительный язык для конкретного пользователя.", "how_to_use":["Прокрутите /settings до секции языка.", "Выберите один из видимых языков.", "Чтобы открыть дополнительные варианты, нажмите More languages и выберите нужный язык."], "result":"Выбор языка сохраняется как пользовательская настройка.", "availability":"Для вошедшего пользователя.", "limits":"Положение секции может отличаться на узком экране; она не является отдельной страницей."},
        {"id":"settings_plan_payment", "areas":["settings","plans"], "screen":"Your profile /settings · CURRENT PLAN", "entry":"На основном экране APRIL нажмите кнопку профиля с именем пользователя в верхней панели справа; откроется Your profile.", "position":"На странице Your profile прокрутите ниже блока USER / Name in chat space. Там расположена карточка CURRENT PLAN; пакеты показаны в нижней части этой карточки, выше блока Delete account.", "control":"CURRENT PLAN со статусом FREE / Free access или активным тарифом; видимые пакеты: 7 days · $12, 28 days · $25, 12 hours · $3. В checkout встречаются Pay и Cancel.", "does":"Показывает действующий уровень доступа и срок; если текущая сборка/состояние аккаунта разрешает покупку, пакет запускает разовую оплату.", "how_to_use":["Откройте основной чат APRIL и нажмите кнопку профиля с вашим именем в верхней панели справа.", "На странице Your profile найдите карточку CURRENT PLAN — она находится ниже USER / Name in chat space.", "Проверьте текущий уровень и время действия, если оно показано.", "Выберите один из пакетов, только если соответствующая кнопка действительно видна: 7 days · $12, 28 days · $25 или 12 hours · $3.", "В появившемся checkout проверьте сумму и условия; Pay подтверждает оплату, Cancel отменяет/закрывает checkout.", "Дождитесь подтверждения платёжного сервиса, вернитесь в Your profile и проверьте обновлённый статус/срок."], "result":"После подтверждения платёжным шлюзом сервер обновляет entitlement и срок действия; статус следует проверить в CURRENT PLAN.", "availability":"Набор пакетов зависит от текущего состояния тарифа и сборки. В Google Play distribution внешние платёжные кнопки скрыты; ориентируйтесь на фактически видимые элементы страницы.", "limits":"Покупки разовые, авто-продление не обещать. Цены в снимке исходников/экрана: 7 days · $12, 28 days · $25, 12 hours · $3. На приложенном экране кнопки Free trial / Start trial нет; тестовый период нельзя утверждать без явного предложения до оплаты. Нельзя объявлять оплату успешной до gateway confirmation."},
        {"id":"history_resume", "areas":["history","settings"], "screen":"История диалогов /history", "entry":"/history напрямую или /settings → CURRENT PLAN → Dialog history, если доступна.", "position":"Основное содержимое страницы — список карточек диалогов.", "control":"Карточка с датой/фрагментом и Continue this dialogue.", "does":"Открывает сохранённый диалог и позволяет продолжить его контекст.", "how_to_use":["Откройте /history.", "Найдите карточку по дате и текстовому фрагменту.", "Нажмите Continue this dialogue."], "result":"Продолжение выбранной беседы.", "availability":"Premium-gated in source snapshot.", "limits":"В просмотренной странице отдельное поисковое поле не найдено; смысловой/временной поиск можно попросить April выполнить из чата."},
        {"id":"community_public_post", "areas":["space"], "screen":"Community /space", "entry":"/settings → CURRENT PLAN → Community или прямой /space.", "position":"Лента сообщества; закреплённая панель публикации внизу. Скрепка Attach a file слева от поля текста, Send справа.", "control":"Ask a question or share a solution… · Attach a file · Send.", "does":"Публикует сообщение и при необходимости один файл в общей ленте, видимые участникам сообщества.", "how_to_use":["Откройте /space и войдите через Google, если требуется.", "В нижней панели нажмите Attach a file слева, если нужно приложить документ/код/архив.", "Выберите поддерживаемый файл до 3 МБ; при необходимости введите текст до 4000 символов.", "Нажмите Send справа. Пост и вложение появятся в общей ленте."], "result":"Публичный пост появляется в общей ленте, а файл становится доступен участникам.", "availability":"Сообщество доступно Free и Premium в исходнике; вход обязателен.", "limits":"Файлы до 3 МБ, активное хранилище вложений до 30 МБ на пользователя; исполняемые типы блокируются, список допустимых расширений ограничен. Публикации и файлы видны сообществу. Не размещайте личные данные, пароли и API-ключи."},
        {"id":"community_invite", "areas":["space"], "screen":"Community /space", "entry":"Откройте /space.", "position":"В верхней части страницы — блок Personal profile и приглашение.", "control":"Invite a friend.", "does":"Формирует ссылку приглашения; передача выполняется через системное меню Share, если браузер его поддерживает, иначе ссылка копируется.", "how_to_use":["Откройте /space.", "Найдите блок профиля/Personal profile и нажмите Invite a friend.", "В системном меню выберите мессенджер/приложение или используйте Copy link."], "result":"Ссылка приглашения передаётся или копируется.", "availability":"После входа.", "limits":"Список мессенджеров зависит от ОС и доступных приложений; сайт не гарантирует конкретный сервис в меню."},
        {"id":"community_friend_manage", "areas":["space"], "screen":"Community /space", "entry":"Откройте /space.", "position":"Секция поиска участников, входящих запросов и списка Friends.", "control":"Search friends, Add friend, Accept, Request sent, Block/Unblock.", "does":"Ищет пользователей, отправляет/принимает запросы дружбы и управляет блокировкой контакта.", "how_to_use":["Откройте /space и найдите блок поиска/контактов.", "Найдите пользователя.", "Нажмите Add friend либо Accept на входящем запросе.", "Проверьте состояние запроса/список друзей; при необходимости используйте Block или Unblock."], "result":"Пользователь добавляется в контакты после подтверждения, либо меняется состояние блокировки.", "availability":"Для авторизованных участников.", "limits":"Не подменяйте публичную публикацию запросом дружбы — это разные действия."},
        {"id":"community_private_chat", "areas":["space","direct"], "screen":"Community → Private chat /space/direct/[friendId]", "entry":"Откройте /space и найдите участника в списке Friends; сначала оба пользователя должны подтвердить дружбу.", "position":"На карточке друга нажмите Private chat. В личном чате вверху слева Back to Community; внизу закреплённая панель: скрепка слева, поле Message your friend… по центру и стрелка Send справа.", "control":"Private chat → Attach file → Message your friend… → Send.", "does":"Открывает личную переписку с выбранным другом; позволяет отправить текст и один файл.", "how_to_use":["Откройте /space и найдите нужного пользователя.", "Если вы ещё не друзья, используйте Add friend; второй пользователь должен принять запрос. Личные сообщения доступны только после взаимного подтверждения.", "На карточке друга нажмите Private chat.", "В нижней панели нажмите скрепку слева и выберите один файл до 3 МБ; исполняемые файлы блокируются.", "Введите сообщение до 4000 символов и нажмите стрелку Send справа. Можно отправить и файл без текста.", "Чтобы вернуться, нажмите Back to Community в верхней левой части."], "result":"Сообщение и вложение появляются в личной переписке выбранных друзей; файл можно скачать через Download file.", "availability":"Авторизация Google и взаимно подтверждённая дружба.", "limits":"Один файл до 3 МБ; исполняемые файлы запрещены. Не вводите [friendId] вручную — маршрут формирует интерфейс. Кнопка Invite to April делится приглашением в April, а не пересылает файл."},
        {"id":"support_send_ticket", "areas":["support"], "screen":"Contact Support /insights?room=support", "entry":"/settings → CURRENT PLAN → Contact support при доступности либо /aprill → Contact Support.", "position":"История обращений выше; форма отправки находится в нижней части страницы.", "control":"Textarea до 4000 символов, кнопка выбора изображения и Send.", "does":"Отправляет техническое обращение и необязательный скриншот.", "how_to_use":["Откройте /insights?room=support.", "Просмотрите историю/ответы.", "Когда форма доступна, опишите проблему (до 4000 символов).", "При необходимости прикрепите PNG/JPG/WebP до 12 МБ и проверьте предпросмотр.", "Нажмите Send и дождитесь ответа/обновления истории."], "result":"Обращение появляется в истории поддержки.", "availability":"В просмотренном исходнике форма для активного Premium; один новый запрос за 24 часа.", "limits":"При cooldown форма недоступна до указанного времени. Это не публичный пост и не кнопка Report под ответом April."},
        {"id":"help_article_navigation", "areas":["guide","help-center","how-to-use","plans","privacy","terms","deletion"], "screen":"Help & Information /aprill", "entry":"Логотип APRIL в верхней панели основного чата.", "position":"Страница /aprill содержит карточки тем; выбор статьи сохраняет родительский адрес и использует hash/внутреннее состояние.", "control":"Help Center, How to Use April, Privacy Policy, Terms of Service, Plans & Payments, Account & Data Deletion, Contact Support.", "does":"Открывает статью/информационный раздел по выбранной теме.", "how_to_use":["Откройте /aprill.", "Нажмите нужную тематическую карточку.", "Читайте открывшуюся статью; кнопка/стрелка назад возвращает к списку тем."], "result":"Открывается содержимое выбранного раздела в Help & Information.", "availability":"Free и Premium.", "limits":"Не все карточки имеют отдельный URL; не выдумывать ссылку на hash, если она не видна в конкретном экране."},
        {"id":"account_delete", "areas":["deletion","settings"], "screen":"Удаление аккаунта April /account-deletion", "entry":"/settings → Delete account или /aprill → Account & Data Deletion.", "position":"Отдельная страница удаления с объяснением и явным подтверждением.", "control":"Delete account / подтверждение удаления.", "does":"Запускает удаление April-профиля и связанных данных после подтверждения.", "how_to_use":["Откройте /account-deletion.", "Внимательно прочитайте, какие данные удаляются.", "Подтвердите действие только если действительно хотите удалить April-аккаунт."], "result":"Запускается удаление April-данных согласно серверной процедуре.", "availability":"Для авторизованного пользователя.", "limits":"Google-аккаунт пользователя не удаляется. Действие необратимо; не нажимайте подтверждение для обычного выхода."},
