def _site_request_intent_layers(machine_request: Any) -> List[Dict[str, Any]]:
    """Collect only known Interpretation envelope layers from a request."""
    if isinstance(machine_request, dict):
        root = machine_request
    else:
        root_value = getattr(machine_request, "intent", {})
        root = root_value if isinstance(root_value, dict) else {}
    sources: List[Dict[str, Any]] = []
    pending: List[Dict[str, Any]] = [root]
    seen: set[int] = set()
    while pending and len(sources) < 12:
        source = pending.pop(0)
        if not isinstance(source, dict) or id(source) in seen:
            continue
        seen.add(id(source))
        sources.append(source)
        for key in ("intent", "interpretation", "request_structure", "semantic_interpretation", "features", "intent_features"):
            child = source.get(key)
            if isinstance(child, dict):
                pending.append(child)
        semantic = source.get("semantic_interpretation")
        if isinstance(semantic, dict):
            pending.append(semantic)
            for feature_key in ("features", "intent_features"):
                features = semantic.get(feature_key)
                if isinstance(features, dict):
                    pending.append(features)
    return sources


def _site_navigation_semantics(machine_request: Any) -> Dict[str, Any]:
    """Find the typed April-UI navigation interpretation regardless of wrapper depth."""
    for source in _site_request_intent_layers(machine_request):
        direct = source.get("site_navigation_semantics")
        if isinstance(direct, dict):
            return direct
        semantic = source.get("semantic_interpretation")
        if isinstance(semantic, dict):
            features = {}
            for feature_key in ("features", "intent_features"):
                candidate = semantic.get(feature_key)
                if isinstance(candidate, dict):
                    features.update(candidate)
            nested = features.get("site_navigation_semantics") or semantic.get("site_navigation_semantics")
            if isinstance(nested, dict):
                return nested
        for feature_key in ("features", "intent_features"):
            nested = source.get(feature_key)
            if isinstance(nested, dict) and isinstance(nested.get("site_navigation_semantics"), dict):
                return nested["site_navigation_semantics"]
    return {}


def _site_is_assistant_owned_content(value: Any) -> bool:
    """Recognize an April-owned answer/message even when adjectives intervene."""
    text = str(value or "").lower().replace("ё", "е")
    return bool(re.search(
        r"(?:\b(?:тво[её]|ваш|ваше|мой|мое|моё|наш|наше)\s+(?:[\w-]+\s+){0,3}(?:ответ|сообщен\w*|реплик\w*)|"
        r"\bответ\w*\s+(?:април\w*|april)\b|\bсообщен\w*\s+(?:април\w*|april)\b|"
        r"\b(?:your|my|our)\s+(?:(?:latest|last|previous|earlier)\s+){0,2}(?:april\s+)?(?:reply|response|message)\b|"
        r"\bapril(?:'s)?\s+(?:latest\s+|last\s+|previous\s+)?(?:reply|response|message)\b|"
        r"(?:котор\w*.{0,35}(?:создал\w*|сгенерировал\w*|подготовил\w*|показал\w*)\s+(?:april|април|ты)|"
        r"(?:april|април|ты)\s+(?:создал\w*|сгенерировал\w*|подготовил\w*|показал\w*).{0,35}(?:файл|код|картинк|изображени|график|таблиц))|"
        r"\b(?:the\s+)?(?:file|code|image|picture|chart|table)\s+(?:you|april)\s+(?:created|generated|made|showed)\b)",
        text, re.I,
    ))


def _site_control_reference_kind(value: Any) -> str:
    """Classify a short follow-up only when it names a concrete known control."""
    text = str(value or "").lower().replace("ё", "е")
    if re.search(r"(?:зел[её]н\w*.{0,24}(?:кнопк\w*|стрелк\w*)|(?:кнопк\w*|стрелк\w*).{0,24}зел[её]н\w*|опубликов\w*.{0,40}сообществ\w*)", text, re.I | re.S):
        return "assistant_response_share"
    if re.search(r"(?:поблагодар\w*|отблагодар\w*|кнопк\w*.{0,20}спасибо|спасибо.{0,20}кнопк\w*|thanks?\s+button)", text, re.I | re.S):
        return "response_feedback_thanks"
    if re.search(r"(?:жалоб\w*|пожалова\w*|кнопк\w*.{0,20}report|report\s+button)", text, re.I | re.S):
        return "response_feedback_report"
    return ""


# A social acknowledgement is a conversational move, not a request to navigate
# the UI. The distinction matters because generic dialogue metadata can mark any
# reaction as a reference to the preceding assistant answer. Do not let that
# metadata resurrect an older "Thanks/Report" button tutorial.
_SOCIAL_ACKNOWLEDGEMENT_RE = re.compile(
    r"(?:\bспасибо\b|\bблагодар\w*|\bпожалуйста\b|\bпризнател\w*|"
    r"\bрад\w*\b.{0,65}\b(?:что|тебе|вам|мне)\b|"
    r"\bпонравил\w*|\bклассно\b|\bкруто\b|\bздорово\b|\bотлично\b|\bсупер\b|"
    r"\bthanks?\b|\bthank\s+you\b|\bappreciat\w*|\bglad\s+to\s+hear\b)",
    re.IGNORECASE,
)
_SOCIAL_ACTION_OR_QUESTION_RE = re.compile(
    r"[?？]"
    r"|\b(?:где|куда|как|зачем|почему|какой|какая|какие|можно\s+ли)\b"
    r"|(?:^|\bа\s+)что\b"
    r"|\b(?:покажи|покажите|объясни|объясните|расскажи|расскажите|найди|найдите|"
    r"открой|откройте|нажми|нажмите|перейди|перейдите|сделай|сделайте|"
    r"помоги|помогите|давай|придумай|сыграем|поиграем|предложи|начни|"
    r"show|where|how|what|which|click|open|find|explain|help|let\s+us|let's|play|suggest)\b",
    re.IGNORECASE,
)
_SITE_UI_OBJECT_REFERENCE_RE = re.compile(
    r"(?:кнопк\w*|стрелк\w*|значк\w*|иконк\w*|жалоб\w*|"
    r"под\s+(?:этим\s+|этим\s+самым\s+)?ответ\w*|"
    r"интерфейс\w*|экран\w*|меню\w*|раздел\w*|страниц\w*|"
    r"переход\w*|ссылк\w*|поле\s+ввод\w*|навигац\w*|"
    r"button\w*|arrow\w*|icon\w*|screen\w*|interface\w*|menu\w*|"
    r"section\w*|page\w*|route\w*|navigation\w*|under\s+(?:the\s+)?(?:answer|reply|message))",
    re.IGNORECASE,
)
_SITE_UI_ELLIPTICAL_QUESTION_RE = re.compile(
    r"(?:не\s+понима\w*.{0,65}\bкуда\b.{0,35}\b(?:пройти|идти|зайти|нажать|перейти)\b|"
    r"\b(?:где|куда|как|что|зачем|почему|какой|какая|какие|where|how|what|which)\b"
    r".{0,55}\b(?:это|этот|эта|эту|там|туда|она|он|они|ее|её|его|ими|так|"
    r"работает|делает|нажать|открыть|пройти|идти|это\s+делать|it|this|that|there|it\s+works|it\s+does)\b|"
    r"\b(?:а\s+)?(?:это|этот|эта|эту|там|туда|она|он|они|ее|её|его)\s*\?+|"
    r"\b(?:а\s+)?(?:она|он|они|это|этот|эта|эту)\s+(?:что\s+)?(?:делает|значит|такое|работает)\s*\?+|"
    r"\bwhat\s+(?:does\s+it\s+do|is\s+it\s+for|does\s+that\s+do)\s*\?+)",
    re.IGNORECASE,
)


def _is_social_acknowledgement_only(value: Any) -> bool:
    """True for thanks/praise/reaction turns with no new question or UI action."""
    text = str(value or "").strip().lower().replace("ё", "е")
    if not text or not _SOCIAL_ACKNOWLEDGEMENT_RE.search(text):
        return False
    # A genuine follow-up or explicit UI reference wins over the gratitude cue:
    # "Спасибо, где кнопка?" must still reach the UI-help resolver.
    if _SOCIAL_ACTION_OR_QUESTION_RE.search(text):
        return False
    if _SITE_UI_OBJECT_REFERENCE_RE.search(text) or _site_control_reference_kind(text):
        return False
    return True


def _has_current_site_ui_reference(value: Any) -> bool:
    """Require the current turn itself to refer to a UI control or ask an elliptical UI question."""
    text = str(value or "").strip().lower().replace("ё", "е")
    return bool(
        text
        and not _is_social_acknowledgement_only(text)
        and (
            _site_control_reference_kind(text)
            or _SITE_UI_OBJECT_REFERENCE_RE.search(text)
            or _SITE_UI_ELLIPTICAL_QUESTION_RE.search(text)
        )
    )


def _is_help_information_plans_topic_query(value: Any) -> bool:
    """Distinguish the informational Plans & Payments article from purchasing Premium."""
    text = str(value or "").strip().lower().replace("ё", "е")
    has_help_surface = bool(re.search(
        r"(?:help\s*(?:&|and)\s*information|help\s+center|справк\w*|центр\s+помощи|/aprill)",
        text, re.I,
    ))
    has_plans_article = bool(re.search(
        r"(?:plans\s*(?:&|and)\s*payments|план\w*\s+и\s+платеж\w*|тариф\w*\s+и\s+платеж\w*)",
        text, re.I,
    ))
    return has_help_surface and has_plans_article


def _is_april_premium_navigation_query(value: Any) -> bool:
    """Recognize a user's navigation request for April's own plan card.

    This deliberately does not classify a generic ChatGPT/third-party subscription
    question as April UI help. April itself, or an explicit "your app" reference,
    must be present alongside a plan/subscription term.
    """
    text = str(value or "").strip().lower().replace("ё", "е")
    if not text:
        return False
    plan = bool(re.search(
        r"(?:\bpremium\b|премиум|платн\w*\s+план|тариф\w*|подписк\w*|"
        r"пробн\w*\s+период|тестов\w*\s+(?:период|доступ)|бесплатн\w*\s+(?:тест|период)|"
        r"free\s+trial|trial\s+period|plan\s*(?:&|and)?\s*payments)",
        text, re.I,
    ))
    april_app = bool(re.search(
        r"(?:\bapril\b|април\w*|эйприл\w*|тво[её]м\s+приложени\w*|в\s+приложени\w*\s+april)",
        text, re.I,
    ))
    return plan and april_app


def _site_semantic_function_targets(query: str, semantic: Dict[str, Any], area_ids: Any = None) -> Dict[str, List[str]]:
    """Resolve an already-interpreted UI operation to the source-derived control catalog.

    The caller supplies the typed April-UI interpretation (or a validated active-UI
    follow-up). This resolver maps intent to controls; it does not infer live state.
    """
    if not isinstance(semantic, dict):
        return {"function_ids": [], "semantic_targets": [], "area_ids": []}
    domain = _text(semantic.get("domain")).lower()
    action = _text(semantic.get("action")).upper()
    if domain != "april_ui" or action not in {"EXPLAIN_UI_ROUTE", "GUIDE_UI_ACTION", "GUIDE_ATTACH_IMAGE"}:
        return {"function_ids": [], "semantic_targets": [], "area_ids": []}
    goal = _text(semantic.get("user_goal"))
    combined = f"{query} {goal}".lower().replace("ё", "е")
    inferred_areas = list(area_ids) if isinstance(area_ids, (list, tuple, set)) else []
    if _is_april_premium_navigation_query(combined):
        return {
            "function_ids": ["settings_plan_payment", "settings_premium_packages"],
            "semantic_targets": ["plans.payment", "settings.payment_packages"],
            # The user buys from the profile's CURRENT PLAN card, not from the
            # similarly named informational card on Help & Information.
            "area_ids": ["settings"],
        }
    for _score, area_id in _semantic_site_area_scores(combined):
        if area_id not in inferred_areas:
            inferred_areas.append(area_id)
    # The semantic operation and object are known here: publish a message in the
    # public Community surface. Do not infer private chat or unrelated profile actions.
    public_feed_operation = bool(
        re.search(r"(?:отправ\w*|публикац\w*|опубликов\w*|размест\w*|созда\w*|написа\w*|поделит\w*|post\w*|publish\w*|create\w*|write\w*|send\w*)", combined)
        and re.search(r"(?:сообщен\w*|пост\w*|публикац\w*|текст\w*|ответ\w*|community|сообществ\w*)", combined)
        and bool(re.search(r"(?:community|сообществ\w*|/space|публичн\w* лент\w*)", combined, re.I))
    )
    if re.search(r"(?:таблиц\w*|table)", combined, re.I) and re.search(r"(?:сортир\w*|скача\w*|копир\w*|download|sort)", combined, re.I):
        return {"function_ids": ["render_table_controls"], "semantic_targets": ["render.table"], "area_ids": ["chat"]}
    if re.search(r"(?:код\w*|code)", combined, re.I) and re.search(r"(?:копир\w*|скача\w*|сохран\w*|copy|download)", combined, re.I):
        return {"function_ids": ["render_code_copy"], "semantic_targets": ["render.code"], "area_ids": ["chat"]}
    if re.search(r"(?:приглас\w*|invite)", combined, re.I) and re.search(r"(?:друг\w*|friend)", combined, re.I) and re.search(r"(?:april|април|community|сообществ)", combined, re.I):
        return {"function_ids": ["community_invite_friend", "community_invite"], "semantic_targets": ["community.invite_friend"], "area_ids": ["space"]}
    if re.search(r"(?:личн\w*\s+чат|приватн\w*\s+чат|private\s+chat)", combined, re.I) and re.search(r"(?:файл|вложен|скача|удалить|download)", combined, re.I):
        return {"function_ids": ["direct_chat_controls"], "semantic_targets": ["direct.chat.controls"], "area_ids": ["space", "direct"]}
    if re.search(r"(?:файл\w*|документ\w*|file)", combined, re.I) and re.search(r"(?:скача\w*|поделит\w*|сохран\w*|download|share)", combined, re.I):
        return {"function_ids": ["render_file_actions"], "semantic_targets": ["render.file"], "area_ids": ["chat"]}
    if re.search(r"(?:полноэкран\w*|увелич\w*|галере\w*|миниатюр\w*|fullscreen|gallery)", combined, re.I):
        return {"function_ids": ["render_gallery_controls"], "semantic_targets": ["render.gallery"], "area_ids": ["chat", "image-controls"]}
    if re.search(r"(?:svg|схем\w*|диаграмм\w*)", combined, re.I) and re.search(r"(?:откры\w*|увелич\w*|закры\w*|скача\w*|поделит\w*|open|close|download|share)", combined, re.I):
        return {"function_ids": ["render_diagram_expand"], "semantic_targets": ["render.diagram"], "area_ids": ["chat"]}
    if re.search(r"(?:ссылк\w*|linkcard|link card)", combined, re.I) and re.search(r"(?:откры\w*|скача\w*|копир\w*|поделит\w*|open|copy|share)", combined, re.I):
        return {"function_ids": ["render_link_open"], "semantic_targets": ["render.link"], "area_ids": ["chat"]}
    if re.search(r"(?:3d\s*(?:график|graph)|график|график\w*|graph|ракурс|масштаб)", combined, re.I) and re.search(r"(?:кнопк|управл|поверн|ракурс|масштаб|приблиз|увелич|уменьш|сброс|данн|описан|zoom|rotate|view)", combined, re.I):
        return {"function_ids": ["rendered_graph_controls"], "semantic_targets": ["rendered_graph.controls"], "area_ids": ["graph-controls", "chat"]}
    if re.search(r"(?:боков\w*\s+панел|панел\w*\s+профил|панел\w*\s+истори|свернут\w*\s+панел|развернут\w*\s+панел|панел\w*\s+слева|side\s+panel|collapse\s+profile|history\s+panel)", combined, re.I):
        return {"function_ids": ["chat_side_panels"], "semantic_targets": ["chat.side_panels"], "area_ids": ["chat", "settings", "history"]}
    free_media_quota_context = bool(re.search(
        r"(?:лимит\w*.{0,40}(?:free|медиа|вложен|изображ|операц)|"
        r"(?:free|бесплатн\w*).{0,40}(?:лимит|медиа|quota|operations)|"
        r"media.{0,20}(?:limit|quota)|quota.{0,20}(?:media|free)|"
        r"6\s+(?:дополнительн\w*\s+)?медиа.?операц|6\s+additional\s+media\s+operations)", combined, re.I,
    ))
    free_referral_action = bool(re.search(
        r"(?:приглаш\w*|ссылк\w*|бонус\w*|дополнительн\w*\s+операц|"
        r"invite|referral|share\s+(?:an?\s+)?(?:invite\s+)?link)", combined, re.I,
    ))
    if free_media_quota_context and free_referral_action:
        return {"function_ids": ["chat_free_media_referral"], "semantic_targets": ["chat.free_media_referral"], "area_ids": ["chat", "settings"]}
    # A question about the complete row must resolve to the complete row before
    # single-control matching gets a chance to select only the green publish action.
    feedback_row_question = bool(
        (
            re.search(r"(?:три\s+кнопк\w*|three\s+buttons|жалоб\w*|поблагодар\w*|спасибо)", combined, re.I)
            and re.search(r"(?:кнопк\w*|под\s+(?:ответ\w*|сообщен\w*)|reply|response)", combined, re.I)
        )
        or re.search(
            r"(?:все\s+(?:эти\s+)?кнопк\w*|all\s+(?:these\s+)?buttons).{0,65}(?:под\s+(?:ответ\w*|сообщен\w*)|under\s+(?:the\s+)?(?:answer|reply|message))",
            combined, re.I | re.S,
        )
    )
    if feedback_row_question:
        return {
            "function_ids": ["response_feedback", "assistant_response_share"],
            "semantic_targets": ["response.feedback", "response.share_to_community"],
            "area_ids": ["response-feedback", "chat", "space"],
        }
    # A known control mentioned in an interpreted April-UI request maps to its exact
    # source component. This is deliberately based on label/position semantics, not colour alone.
    control_kind = _site_control_reference_kind(combined)
    if control_kind == "assistant_response_share":
        return {
            "function_ids": ["assistant_response_share"],
            "semantic_targets": ["response.share_to_community"],
            "area_ids": ["response-feedback", "chat", "space"],
        }
    if control_kind in {"response_feedback_thanks", "response_feedback_report"}:
        return {
            "function_ids": ["response_feedback"],
            "semantic_targets": ["response.feedback"],
            "area_ids": ["response-feedback", "chat"],
        }
    # Resolve the other Community controls independently. A normal friend
    # invitation must not be mistaken for the Free media-referral modal.
    community_context = "space" in inferred_areas or bool(re.search(r"(?:community|сообществ\w*|\bspace\b)", combined, re.I))
    if community_context and re.search(r"(?:личн\w*\s+чат|приватн\w*\s+чат|private\s+chat|direct\s+message|написат\w*.{0,40}друг\w*)", combined, re.I):
        return {"function_ids": ["community_private_chat", "direct_chat_controls"], "semantic_targets": ["community.private_chat", "direct.chat.controls"], "area_ids": ["space", "direct"]}
    history_search_ui_question = bool(re.search(
        r"(?:где\s+(?:находится\s+)?поиск|есть\s+ли\s+поиск|поле\s+поиска|как\s+(?:найти|открыть|пользоваться)\s+(?:строк\w*\s+)?поиск|search\s+(?:field|box))",
        combined, re.I,
    )) and bool(re.search(r"(?:истори\w*|диалог\w*|history|conversation)", combined, re.I))
    if history_search_ui_question:
        return {"function_ids": ["history_resume"], "semantic_targets": ["dialogue_history.search_availability"], "area_ids": ["history", "chat"]}
    site_wide_search_question = bool(re.search(
        r"(?:поиск\w*.{0,35}(?:по\s+)?(?:вс\w*\s+)?сайт\w*|поиск\w*.{0,35}глобальн\w*|глобальн\w*.{0,35}поиск|search\s+(?:the\s+)?(?:whole\s+)?site|site[- ]wide\s+search)",
        combined, re.I | re.S,
    ))
    community_member_search_question = bool(re.search(
        r"(?:найти\w*.{0,30}(?:друз|пользоват)|поиск\w*.{0,30}(?:друз|пользоват)|добав\w*.{0,30}друз|запрос\w*.{0,30}друз|принят\w*.{0,30}запрос|accept\s+friend|add\s+friend|search\s+friends|block|unblock)",
        combined, re.I,
    ))
    if community_context and community_member_search_question:
        return {"function_ids": ["community_friend_manage"], "semantic_targets": ["community.friends"], "area_ids": ["space"]}
    if site_wide_search_question:
        # There is no global site-search control in this Web source snapshot.
        # Point to the only real search field while clearly stating its narrow scope.
        return {"function_ids": ["community_friend_manage"], "semantic_targets": ["site.search_availability"], "area_ids": ["space"]}
    if community_context and re.search(r"(?:личн\w*\s+профил|community\s+profile|никнейм|ник\b|nickname|save\s+nickname)", combined, re.I):
        return {"function_ids": ["community_personal_profile"], "semantic_targets": ["community.personal_profile"], "area_ids": ["space"]}
    if community_context and re.search(r"(?:удал\w*.{0,50}(?:сво[юеё]\s+)?(?:сообщен|публикац|пост)|жалоб\w*.{0,40}(?:пост|публикац|сообщен)|пожалова\w*.{0,40}(?:пост|публикац)|скача\w*.{0,40}(?:вложен|файл)|delete\s+(?:your\s+)?(?:post|message)|report\s+(?:a\s+)?post|download\s+file)", combined, re.I):
        return {"function_ids": ["community_post_actions"], "semantic_targets": ["community.post_actions"], "area_ids": ["space"]}
    if community_context and re.search(r"(?:приглас\w*.{0,40}друг|друг\w*.{0,40}приглас\w*|invite\s+(?:a\s+)?friend|friend\s+invitation)", combined, re.I):
        return {"function_ids": ["community_invite"], "semantic_targets": ["community.invite"], "area_ids": ["space"]}
    if public_feed_operation:
        # The semantic object role matters: a request to publish "your/April's
        # answer" maps to the green action beneath an assistant reply, while a
        # request to write a new post maps to the Community composer.
        assistant_owned_content = _site_is_assistant_owned_content(combined)
        if assistant_owned_content:
            return {
                "function_ids": ["assistant_response_share"],
                "semantic_targets": ["response.share_to_community"],
                "area_ids": ["response-feedback", "chat", "space"],
            }
        return {
            "function_ids": ["community_public_post"],
            "semantic_targets": ["community.public_post"],
            "area_ids": ["space"],
        }
    return {"function_ids": [], "semantic_targets": [], "area_ids": inferred_areas[:4]}



def _site_focused_function_candidates(query: str, area_ids: List[str]) -> List[str]:
    """Resolve the specific current UI action, not every control on a related page.

    This is a compatibility resolver for callers that have no typed action_contract.
    When Interpretation supplies `domain=april_ui`, target/action and requested_outputs,
    those structured values take precedence in _select_ui_function_catalog.
    """
    q = str(query or "").lower().replace("ё", "е")
    ids = set(area_ids or [])
    out: List[str] = []

    def add(*values: str) -> None:
        for value in values:
            if value not in out:
                out.append(value)

    # High-specificity current operation resolution, before broad page overlap.
    # Plans & Payments inside Help & Information is an article card, not checkout.
    if _is_help_information_plans_topic_query(q):
        add("help_article_navigation", "help_topic_cards")
        return out
    if _is_april_premium_navigation_query(q):
        add("settings_plan_payment", "settings_premium_packages")
        return out
    if re.search(r"(?:сменить|изменить|поменять|выбрать).{0,35}(?:язык|language)|(?:язык|language).{0,35}(?:сменить|изменить|выбрать)", q, re.I):
        add("settings_language")
        return out
    if re.search(r"(?:микрофон|голосов\w* сообщен|голосом|voice\s+(?:message|input)).{0,45}(?:чат|april|отправ|запис|сообщен|voice)?|(?:отправить|записать).{0,35}голосов\w*", q, re.I):
        add("chat_voice_input")
        return out
    if re.search(r"(?:убрать|удалить|открепить|снять).{0,45}(?:вложен|прикреплен|фото|картин|файл|attachment)|(?:remove|delete).{0,35}(?:attachment|file|image)", q, re.I):
        add("chat_attachment_picker_controls")
        return out
    if re.search(r"(?:заблокировать|разблокировать|block|unblock)", q, re.I):
        add("community_block_member")
        return out
    if re.search(r"(?:личн\w*|приватн\w*|private).{0,35}(?:чат|переписк|сообщен)|(?:чат|переписк).{0,35}(?:с\s+друг|личн|private)", q, re.I):
        add("community_private_chat", "direct_chat_controls")
        return out
    if re.search(r"(?:скриншот|снимок экрана).{0,45}(?:поддержк|обращен|support)|(?:поддержк|support).{0,45}(?:скриншот|screenshot)", q, re.I):
        add("support_attach_screenshot")
        return out
    if re.search(r"(?:истори\w* обращен|прошл\w* обращен|открыть обращен|выбрать тикет|support ticket history|open ticket)", q, re.I):
        add("support_thread_select")
        return out
    if re.search(r"(?:отправить|создать|написать).{0,45}(?:обращен|запрос).{0,25}(?:поддержк|support)|(?:поддержк|support).{0,45}(?:обращен|запрос|тикет|ticket)", q, re.I):
        add("support_new_request", "support_send_ticket")
        return out
    if re.search(r"(?:все темы|all topics|назад к темам|вернуться.{0,45}(?:к\s*)?(?:списку\s+)?все\w*\s+тем\w*|вернуться.{0,45}к\s+списку\s+тем\w*|back to topics|back to april)", q, re.I):
        add("help_topic_back_controls")
        return out
    if re.search(r"(?:открыть|развернуть|раскрыть|увеличить).{0,35}(?:svg|схем\w*|диаграмм\w*)|(?:svg|схем\w*|диаграмм\w*).{0,35}(?:открыть|развернуть|раскрыть|увеличить)", q, re.I):
        add("render_diagram_expand")
        return out
    if re.search(r"(?:открыть|развернуть|увеличить|на весь экран).{0,35}(?:картинк\w*|изображен\w*|фото)|(?:картинк\w*|изображен\w*|фото).{0,35}(?:на весь экран|fullscreen|полный экран)", q, re.I):
        add("render_gallery_controls")
        return out
    if re.search(r"(?:открыть|перейти по|нажать).{0,40}(?:внешн\w* ссылк|ссылк\w* в карточк)|(?:external link|link card).{0,35}(?:open|click)", q, re.I):
        add("render_link_open")
        return out
    if re.search(r"(?:отменить|управлять|проверить).{0,45}(?:подписк\w* google play|google play subscription)|(?:google play subscription).{0,35}(?:cancel|manage)", q, re.I):
        add("account_deletion_external_subscription_link")
        return out
    if re.search(r"(?:скопировать|копировать|скачать).{0,35}(?:код|code)|(?:код|code).{0,35}(?:скопировать|копировать|скачать)", q, re.I):
        add("render_code_copy")
        return out
    if re.search(r"(?:сортировать|сортировка).{0,40}(?:таблиц|столбц|колонк)|(?:таблиц|столбц|колонк).{0,40}(?:сортировать|сортировка)", q, re.I):
        add("render_table_controls")
        return out

    control_kind = _site_control_reference_kind(q)
    if re.search(r"(?:community|сообществ|пост|публикац)", q, re.I) and re.search(r"(?:пожалова|жалоб|report|удал\w*)", q, re.I):
        add("community_post_actions", "community_report_post" if re.search(r"(?:пожалова|жалоб|report)", q, re.I) else "community_delete_post")
        return out
    if _site_search_availability_target(q) == "global":
        add("site_search_scope")
        return out
    if control_kind in {"response_feedback_thanks", "response_feedback_report"}:
        add("response_feedback")
        return out
    if control_kind == "assistant_response_share":
        add("assistant_response_share")
        return out

    # Account and plan operations must not pull every profile widget into the answer.
    if re.search(r"(?:войти|авториз|sign\s*in|log\s*in).{0,55}(?:google|аккаунт|april)|(?:google|аккаунт|april).{0,55}(?:войти|авториз|sign\s*in|log\s*in)", q, re.I):
        add("auth_google_sign_in")
        return out
    if re.search(r"(?:обновить|проверить|перепроверить).{0,35}(?:статус|тариф|подписк)|(?:refresh|check).{0,35}subscription", q, re.I):
        add("settings_plan_refresh")
        return out
    if "plans" in ids and re.search(r"(?:купить|оплатить|продлить|renew|buy|pay|checkout|плат[её]ж)", q, re.I):
        add("settings_plan_payment", "settings_premium_packages")
        return out
    if "settings" in ids and re.search(r"(?:мой|твой|ваш)?\s*(?:april\s*id|premium\s*id|идентификатор)", q, re.I):
        add("settings_copy_ids")
        return out
    if "settings" in ids and re.search(r"(?:имя|никнейм|display\s*name).{0,35}(?:измен|смен|помен|edit)|(?:измен|смен|помен).{0,35}(?:имя|никнейм)", q, re.I):
        add("settings_display_name")
        return out
    if "settings" in ids and re.search(r"(?:язык|language).{0,35}(?:смен|измен|выбрать)|(?:смен|измен).{0,35}(?:язык|language)", q, re.I):
        add("settings_language")
        return out
    if "settings" in ids and re.search(r"(?:выйти|выход|разлогин|log\s*out|sign\s*out)", q, re.I):
        add("settings_logout")
        return out
    if "settings" in ids and re.search(r"(?:обновить|проверить).{0,35}(?:тариф|подписк|статус)|(?:refresh|check).{0,35}subscription", q, re.I):
        add("settings_plan_refresh")
        return out

    # History: no search box in the actual page. These are the real list actions.
    if "history" in ids:
        if re.search(r"(?:продолж|восстанов|открыть|вернуться).{0,45}(?:диалог|бесед|разговор)|(?:continue|resume).{0,30}(?:dialog|conversation)", q, re.I):
            add("history_resume", "history_continue_entry")
        elif re.search(r"(?:куда|где|как).{0,45}(?:истори|history)|(?:истори|history).{0,45}(?:открыть|найти|перейти)", q, re.I):
            add("history_resume", "history_back_to_chat")
        if out:
            return out

    # A generated/created artifact in an April answer belongs to that answer's
    # renderer, not to the Community file-download actions that share the word "file".
    assistant_created = _site_is_assistant_owned_content(q) or bool(re.search(
        r"(?:котор\w*.{0,35}(?:создал\w*|сгенерировал\w*|подготовил\w*)\s+(?:april|април|ты)|"
        r"(?:april|април|ты)\s+(?:создал\w*|сгенерировал\w*|подготовил\w*).{0,35}(?:файл|код|картинк|изображени|график|таблиц)|"
        r"(?:file|code|image|picture|chart|table)\s+(?:you|april)\s+(?:created|generated|made))", q, re.I,
    ))
    if assistant_created:
        if re.search(r"(?:файл|документ|file|document|архив|archive)", q, re.I) and re.search(r"(?:скача|сохран|подел|download|save|share)", q, re.I):
            add("render_file_actions")
            return out
        if re.search(r"(?:код|code)", q, re.I) and re.search(r"(?:скопир|копир|скача|download|copy|share)", q, re.I):
            add("render_code_copy")
            return out
        if re.search(r"(?:картинк|изображени|фото|image|picture)", q, re.I) and re.search(r"(?:скача|сохран|подел|download|save|share)", q, re.I):
            add("render_gallery_controls", "rendered_artifact_menu")
            return out
        if re.search(r"(?:таблиц|table)", q, re.I):
            add("render_table_controls")
            return out
        if re.search(r"(?:график|graph)", q, re.I):
            add("rendered_graph_controls")
            return out

    # Community surfaces are split by the actual operation, not the common route.
    if "space" in ids:
        if re.search(r"(?:поиск|найти|искать|добавить|добавля|add).{0,45}(?:друг|пользоват|участник)|(?:друг|пользоват|участник).{0,45}(?:поиск|найти|добав|add)|search\s+friends|add\s+friend", q, re.I):
            add("community_search_members")
            return out
        if re.search(r"(?:заблок|разблок|block|unblock)", q, re.I):
            add("community_block_member")
            return out
        if re.search(r"(?:приглас|invite).{0,35}(?:друг|friend)|(?:друг|friend).{0,35}(?:приглас|invite)", q, re.I):
            add("community_invite_friend", "community_invite")
            return out
        if re.search(r"(?:ник|nickname|личн\w* профил|community profile)", q, re.I):
            add("community_personal_profile", "community_profile_toggle")
            return out
        if re.search(r"(?:личн\w* чат|приватн\w* чат|private\s+chat|личн\w* сообщен)", q, re.I):
            add("community_private_chat", "direct_chat_controls")
            return out
        if re.search(r"(?:удал\w*).{0,40}(?:пост|сообщен)|(?:пожалова|жалоб).{0,40}(?:пост|сообщен)|(?:скача\w*).{0,35}файл", q, re.I):
            add("community_post_actions", "community_delete_post", "community_report_post")
            return out
        if re.search(r"(?:написать|опубликовать|создать|отправить).{0,40}(?:пост|сообщен|вопрос)|(?:общ\w* лент|публичн\w* пост)", q, re.I):
            add("community_public_post")
            return out

    # Renderer controls: exact control family for the user's referenced artifact.
    if re.search(r"(?:таблиц|table).{0,45}(?:сортир|скача|подел|меню)|(?:сортир|сортировк).{0,45}(?:таблиц|колонк)|(?:колонк).{0,35}(?:по возрастан|по убыв|сортир)", q, re.I):
        add("render_table_controls")
        return out
    if re.search(r"(?:код|code).{0,45}(?:скопир|копир|скача|download)|(?:скопир|копир).{0,35}(?:код|code)", q, re.I):
        add("render_code_copy")
        return out
    if re.search(r"(?:файл|документ).{0,45}(?:скача|подел|открыть)|(?:скача|подел).{0,35}(?:файл|документ)", q, re.I) and ("chat" in ids):
        add("render_file_actions")
        return out
    if re.search(r"(?:картинк|изображени|фото).{0,45}(?:полный экран|увелич|скача|подел)|(?:скача|подел).{0,35}(?:картинк|изображени|фото)", q, re.I):
        add("render_gallery_controls", "rendered_artifact_menu")
        return out
    if re.search(r"(?:схем|диаграмм).{0,45}(?:увелич|откры|скача|подел)|(?:открыть|увеличить).{0,35}(?:схем|диаграмм)", q, re.I):
        add("render_diagram_expand")
        return out
    if re.search(r"(?:ссылк|link).{0,45}(?:откры|перейти|скача|подел)|(?:открыть|перейти).{0,35}(?:ссылк|link)", q, re.I) and ("chat" in ids):
        add("render_link_open")
        return out
    if "graph-controls" in ids or re.search(r"(?:график|graph).{0,55}(?:ракурс|повер|масштаб|приблиз|увелич|уменьш|сброс|данн|волна)|(?:ракурс|масштаб|повернуть|приблизить|сбросить вид).{0,45}(?:график|graph)", q, re.I):
        add("rendered_graph_controls")
        return out

    # Composer actions on the actual chat surface.
    if "attachments" in ids or re.search(r"(?:прикреп|загруз|добав).{0,35}(?:фото|картин|файл)|(?:скрепк|камера|выбрать фото)", q, re.I):
        add("chat_attach_file", "chat_attachment_picker_controls")
        return out
    if re.search(r"(?:голос|микрофон|диктов|voice)", q, re.I) and "chat" in ids:
        add("chat_voice_input")
        return out
    if re.search(r"(?:очистить|стереть).{0,35}(?:чат|рабоч|переписк)|(?:метла|clear workspace)", q, re.I):
        add("chat_clear_workspace")
        return out
    if re.search(r"(?:боков\w* панел|свернуть панел|развернуть панел)", q, re.I):
        add("chat_profile_panel_toggle", "chat_history_panel_toggle")
        return out

    # If a query asks for all controls on a specific page, return that page's inventory.
    if ids and re.search(r"(?:все|кажд\w*|полный|полностью|весь|всю).{0,45}(?:кноп|функци|действ|контрол|элемент)|(?:all|every|complete).{0,45}(?:button|control|action|function)", q, re.I):
        for area_id in area_ids:
            add(*_UI_AREA_FUNCTION_IDS.get(area_id, []))
        return out

    return out


def _select_ui_function_catalog(machine_request: Any, site_map: Dict[str, Any]) -> Dict[str, Any]:
    """Select function-level help from the semantic route and action targets."""
    areas = site_map.get("areas") if isinstance(site_map, dict) else []
    area_ids = [str(item.get("id")) for item in areas if isinstance(item, dict) and item.get("id")]
    query = _current_user_query(machine_request).lower().replace("ё", "е")
    overview = _site_full_interface_overview_requested(query)
    requested: set[str] = set()
    search_target = _site_search_availability_target(query)
    if search_target == "global":
        requested.add("site_search_scope")
    elif search_target == "history":
        requested.add("history_resume")
    contracts = _site_ui_action_contracts(machine_request)
    intent_sources = _site_request_intent_layers(machine_request)
    carried_function_ids: List[str] = []
    carried_semantic_targets: List[str] = []
    for source in intent_sources:
        for value in source.get("site_navigation_target_functions", []) if isinstance(source.get("site_navigation_target_functions"), list) else []:
            if isinstance(value, str) and value not in carried_function_ids:
                carried_function_ids.append(value)
        for value in source.get("site_navigation_semantic_targets", []) if isinstance(source.get("site_navigation_semantic_targets"), list) else []:
            if isinstance(value, str) and value not in carried_semantic_targets:
                carried_semantic_targets.append(value)
    semantic_navigation = _site_navigation_semantics(machine_request)
    semantic_fallback = (
        {"domain": "april_ui", "action": "GUIDE_UI_ACTION", "user_goal": query}
        if not semantic_navigation and not contracts and _site_direct_function_intent(query)
        else {}
    )
    semantic_resolved = _site_semantic_function_targets(query, semantic_navigation or semantic_fallback, area_ids)
    for value in semantic_resolved.get("function_ids", []):
        if value not in carried_function_ids:
            carried_function_ids.append(value)
    for value in semantic_resolved.get("semantic_targets", []):
        if value not in carried_semantic_targets:
            carried_semantic_targets.append(value)
    semantic_targets: list[str] = list(carried_semantic_targets)
    requested.update(carried_function_ids)
    for contract in contracts:
        ui_navigation = contract.get("ui_navigation") if isinstance(contract.get("ui_navigation"), dict) else {}
        values = ui_navigation.get("targets") if isinstance(ui_navigation.get("targets"), list) else []
        primary = _text(ui_navigation.get("target") or contract.get("target"))
        for value in ([primary] if primary else []) + list(values):
            value = _text(value)
            if value and value != "verified_site_map" and value not in semantic_targets:
                semantic_targets.append(value)
    target_functions = {
        "response.feedback": ["response_feedback"],
        "response.share_to_community": ["assistant_response_share"],
        "chat.clear_workspace": ["chat_clear_workspace"],
        "chat.paperclip_picker": ["chat_attach_file"],
        "chat.voice_input": ["chat_voice_input"],
        "chat.composer": ["chat_text_send"],
        "rendered_artifact.actions": ["rendered_artifact_menu"],
        "rendered_graph.controls": ["rendered_graph_controls"],
        "chat.side_panels": ["chat_side_panels"],
        "chat.free_media_referral": ["chat_free_media_referral"],
        "profile.display_name": ["settings_display_name"],
        "profile.settings": ["chat_open_profile"],
        "profile.language": ["settings_language"],
        "profile.identifiers": ["settings_copy_ids"],
        "profile.plan": ["settings_plan_payment"],
        "plans.payment": ["settings_plan_payment"],
        "dialogue_history": ["history_resume"],
        "community.public_post": ["community_public_post"],
        "community.invite": ["community_invite"],
        "community.friends": ["community_friend_manage"],
        "community.private_chat": ["community_private_chat", "direct_chat_controls"],
        "support.request": ["support_send_ticket"],
        "april.help_information": ["help_article_navigation"],
        "account.delete": ["account_delete"],
        "legal.privacy": ["help_article_navigation"],
        "legal.terms": ["help_article_navigation"],
    }
    target_functions.update({
        "chat.profile_panel": ["chat_profile_panel_toggle"],
        "chat.support_notice": ["chat_support_notice"],
        "chat.attachment_picker": ["chat_attachment_picker_controls"],
        "chat.free_media_limit": ["chat_free_media_limit_dialog"],
        "history.continue": ["history_continue_entry"],
        "settings.plan_refresh": ["settings_plan_refresh"],
        "settings.payment_packages": ["settings_premium_packages"],
        "settings.support": ["settings_support_drawer"],
        "community.profile": ["community_profile_toggle"],
        "community.search_members": ["community_search_members"],
        "community.block_member": ["community_block_member"],
        "community.invite_friend": ["community_invite_friend"],
        "community.report_post": ["community_report_post"],
        "community.delete_post": ["community_delete_post"],
        "direct.composer": ["direct_chat_controls"],
        "direct.chat.controls": ["direct_chat_controls"],
        "support.thread": ["support_thread_select"],
        "support.attach_screenshot": ["support_attach_screenshot"],
        "help.topic_cards": ["help_topic_cards"],
        "render.table": ["render_table_controls"],
        "render.code": ["render_code_copy"],
        "render.file": ["render_file_actions"],
        "render.gallery": ["render_gallery_controls"],
        "render.diagram": ["render_diagram_expand"],
        "render.link": ["render_link_open"],
    })
    for target in semantic_targets:
        for canonical, function_ids in target_functions.items():
            if target == canonical or target.startswith(canonical + "."):
                requested.update(function_ids)
    if not requested:
        requested.update(_site_focused_function_candidates(query, area_ids))
    if not requested:
        for area_id in area_ids:
            requested.update(_UI_AREA_FUNCTION_IDS.get(area_id, []))
    if overview:
        requested = {str(item.get("id")) for item in APRIL_UI_FUNCTION_CATALOG["functions"] if isinstance(item, dict)}
    functions = [dict(item) for item in APRIL_UI_FUNCTION_CATALOG["functions"] if isinstance(item, dict) and item.get("id") in requested]
    return {
        "schema": APRIL_UI_FUNCTION_CATALOG["schema"],
        "source_note": APRIL_UI_FUNCTION_CATALOG["source_note"],
        "selected_areas": area_ids,
        "functions": functions,
        "full_inventory": bool(overview),
        "semantic_targets": semantic_targets,
    }


