def _ui_search_terms(value: Any) -> set[str]:
    text = str(value or "").lower().replace("ё", "е")
    tokens = set(re.findall(r"[a-zа-яіїє0-9]{3,}", text, re.I))
    stop = {"как", "куда", "где", "что", "мне", "тебя", "твой", "твое", "твоем", "это", "для", "или", "and", "the", "with", "where", "what", "how", "you", "your", "into", "from"}
    tokens.difference_update(stop)
    synonyms = {
        "премиум": {"premium", "подписка", "тариф", "оплата", "план"},
        "premium": {"премиум", "подписка", "тариф", "оплата", "план"},
        "подключить": {"активировать", "оформить", "купить", "оплатить", "premium", "премиум"},
        "активировать": {"подключить", "оформить", "купить", "оплатить"},
        "профиль": {"settings", "настройки", "account", "кабинет"},
        "настройки": {"профиль", "settings", "account"},
        "сообщество": {"community", "space", "друзья"},
        "справка": {"help", "information", "support"},
        "скрепка": {"вложение", "файл", "фото", "attachment"},
    }
    expanded = set(tokens)
    for token in tuple(tokens):
        expanded.update(synonyms.get(token, set()))
    return expanded


def search_april_ui(query: str, limit: int = 4) -> Dict[str, Any]:
    """Search real April screens and control records; return a compact UI answer basis.

    This is the IT room's local interface searcher. It searches both screenshot-seen
    labels/positions and the source-derived function catalogue, never internal room
    names or unverified API routes as if they were user-facing controls.
    """
    q = str(query or "").strip()[:1200]
    terms = _ui_search_terms(q)
    plan_query = _is_april_premium_navigation_query(q)
    screens = APRIL_UI_SCREEN_EVIDENCE.get("screens", [])
    screen_rows = []
    for screen in screens:
        screen_text = " ".join([
            str(screen.get("id", "")), str(screen.get("title", "")), str(screen.get("route", "")),
            " ".join(screen.get("aliases", [])), " ".join(screen.get("visible_labels", [])),
            str(screen.get("position", "")),
        ])
        screen_terms = _ui_search_terms(screen_text)
        score = 3 * len(terms & screen_terms)
        if plan_query and screen.get("id") == "profile_plan":
            score += 100
        if score:
            screen_rows.append((score, screen))
    screen_rows.sort(key=lambda row: row[0], reverse=True)

    function_rows = []
    for item in APRIL_UI_FUNCTION_CATALOG.get("functions", []):
        if not isinstance(item, dict):
            continue
        fields = [item.get(key, "") for key in ("id", "screen", "entry", "position", "control", "does", "availability", "limits")]
        fields.extend(item.get("how_to_use", []) if isinstance(item.get("how_to_use"), list) else [])
        item_terms = _ui_search_terms(" ".join(map(str, fields)))
        score = 2 * len(terms & item_terms)
        if plan_query and item.get("id") in {"settings_plan_payment", "settings_premium_packages"}:
            score += 100
        if score:
            function_rows.append((score, item))
    function_rows.sort(key=lambda row: row[0], reverse=True)

    chosen_screens = []
    for _score, screen in screen_rows[:2]:
        chosen_screens.append({
            "id": screen.get("id"), "route": screen.get("route"), "title": screen.get("title"),
            "position": screen.get("position"), "visible_labels": list(screen.get("visible_labels", [])),
            "controls": list(screen.get("controls", []))[:8],
            **({"trial_evidence": screen.get("trial_evidence")} if screen.get("trial_evidence") else {}),
        })
    chosen_functions = []
    seen_ids = set()
    preferred_ids = ["settings_plan_payment", "settings_premium_packages"] if plan_query else []
    ordered_functions = [item for _score, item in function_rows]
    if preferred_ids:
        ordered_functions.sort(key=lambda item: 0 if item.get("id") in preferred_ids else 1)
    for item in ordered_functions:
        item_id = str(item.get("id") or "")
        if item_id in seen_ids:
            continue
        seen_ids.add(item_id)
        chosen_functions.append({
            "id": item_id, "screen": item.get("screen"), "entry": item.get("entry"),
            "position": item.get("position"), "control": item.get("control"),
            "purpose": item.get("does"), "steps": list(item.get("how_to_use", []))[:7],
            "result": item.get("result"), "availability": item.get("availability"),
            "limits": item.get("limits"),
        })
        if len(chosen_functions) >= (2 if plan_query else max(1, min(int(limit or 4), 4))):
            break

    return {
        "schema": "april.ui_search_result.v1", "query": q,
        "domain": "april_ui", "focused_intent": "premium_plan_navigation" if plan_query else "screen_and_control_lookup",
        "screen_matches": chosen_screens, "control_matches": chosen_functions,
        "evidence_source": APRIL_UI_SCREEN_EVIDENCE.get("source", ""),
        "evidence_limits": APRIL_UI_SCREEN_EVIDENCE.get("limits", ""),
    }


def _select_user_journeys(query: str) -> list[dict]:
    """Return a small relevant workflow excerpt without guessing unseen UI controls."""
    low = _text(query).lower().replace("ё", "е")
    if _is_external_community_topic(low):
        return []
    assistant_owned_content = bool(re.search(
        r"(?:\b(?:тво[её]|ваш|ваше|мой|мое|моё|наш|наше)\s+(?:ответ|сообщен\w*)|"
        r"\bответ\w*\s+(?:април\w*|april)\b|\bсообщен\w*\s+(?:април\w*|april)\b|"
        r"\b(?:your|my|our)\s+(?:april\s+)?(?:reply|response|message)\b|\bapril(?:'s)?\s+(?:reply|response|message)\b)",
        low, re.I,
    ))
    public_post_intent = bool(re.search(r"(?:отправ\w*|пересыл\w*|опубликов\w*|публикац\w*|размест\w*|post\w*|publish\w*|send\w*)", low, re.I)) and bool(re.search(r"(?:сообществ\w*|community)", low, re.I))
    if assistant_owned_content and public_post_intent:
        journey = APRIL_USER_JOURNEYS.get("response-share-community")
        return [{"id": "response-share-community", **journey}] if isinstance(journey, dict) else []
    result = []
    feedback_target = bool(re.search(r"(?:отблагодар\w*|поблагодар\w*|спасибо.{0,45}(?:кноп|наж|где|куда)|пожалова\w*|жалоб\w*|feedback\s+button|report\s+(?:button|response))", low, re.I))
    feedback_location = bool(re.search(r"(?:куда.{0,40}наж|где.{0,70}(?:кноп|наход|это)|кноп\w*.{0,60}(?:под\s+(?:ответ|сообщ)|где|наж)|покажи.{0,60}(?:где|куда|путь)|where.{0,60}(?:click|button|find))", low, re.I | re.S))
    if feedback_target and feedback_location and not re.search(r"(?:создай|сгенерир\w*|построй|нарисуй|напиши|generate|create|build|write).{0,60}(?:график|код|картинк|изображени|graph|code|image)", low, re.I | re.S):
        journey = APRIL_USER_JOURNEYS.get("response-feedback")
        return [{"id": "response-feedback", **journey}] if isinstance(journey, dict) else []
    if re.search(r"(?:создай|сгенерируй|нарисуй|изобрази)\s+(?:мне\s+)?(?:нов\w*\s+)?(?:картинк\w*|изображени\w*|иллюстраци\w*|\bimage\b|\bpicture\b)", low, re.I):
        return []
    if "_is_attachment_instruction_query" in globals() and _is_attachment_instruction_query(query):
        journey = APRIL_USER_JOURNEYS.get("attach_image")
        if isinstance(journey, dict):
            result.append({"id": "attach_image", **journey})
    existing_ids = {str(item.get("id")) for item in result if isinstance(item, dict)}
    for journey_id, journey in APRIL_USER_JOURNEYS.items():
        if journey_id in existing_ids:
            continue
        aliases = journey.get("aliases", [])
        if any(str(alias).lower().replace("ё", "е") in low for alias in aliases):
            result.append({"id": journey_id, **journey})
            existing_ids.add(journey_id)
    if not result:
        ids = [area_id for score, area_id in _semantic_site_area_scores(low) if score >= 2.0]
        mapping = {"attachments":"attach_image", "image-controls":"download_image", "history":"resume_history", "settings":"profile_language_plan", "space":"community", "guide":"get_help", "help-center":"get_help", "how-to-use":"get_help"}
        for area_id in ids:
            if area_id == "attachments" and not ("_is_attachment_instruction_query" in globals() and _is_attachment_instruction_query(query)):
                continue
            if area_id == "image-controls" and not re.search(r"(?:скача\w*|сохран\w*|поделит\w*|download|save|share)", low):
                continue
            if area_id == "space" and not re.search(r"(?:сообществ|community|пользоват|участник|друз|контакт|личн\w*\s+чат|private chat)", low):
                continue
            if area_id == "history" and not re.search(r"(?:истори|сохраненн\w*|стар\w*\s+диалог|предыдущ\w*\s+разговор|continue this dialogue|saved dialogues)", low):
                continue
            if area_id == "settings" and not re.search(r"(?:профил|кабинет|настройк|язык|april id|premium id|тариф|подписк|аккаунт|settings)", low):
                continue
            journey_id = mapping.get(area_id)
            if journey_id and journey_id in APRIL_USER_JOURNEYS and APRIL_USER_JOURNEYS[journey_id] not in result:
                result.append({"id": journey_id, **APRIL_USER_JOURNEYS[journey_id]})
    return result[:3]


