_SITE_GUIDE_TOPIC_RE = re.compile(r"(?:\b(?:api|endpoint|route|маршрут api|api-?шлюз|архитектур\w*|цепочк\w*|пайплайн|какие комнаты|список комнат|room directory|внутренн\w* комнат|создател\w*|кто создал|разработчик\w*|кто автор|какие функци\w*|возможност\w*|free.{0,20}premium|premium.{0,20}free)\b)", re.IGNORECASE)

def _site_words(value: Any) -> set[str]:
    text = str(value or "").lower().replace("ё", "е")
    words = re.findall(r"[a-zа-яіїєґ0-9]+", text, flags=re.IGNORECASE)
    return {word for word in words if len(word) > 2 and word not in _SITE_STOPWORDS}

def _is_external_community_topic(query: Any) -> bool:
    """Keep external IT/AI communities separate from April's own /space route.

    A bare section name or an explicit in-app action may still navigate to April
    Community. A topical question about current IT/AI developments must remain an
    information request even when it contains the word "community/сообщество".
    """
    low = str(query or "").lower().replace("ё", "е").strip()
    if not low or not re.search(r"(?:сообществ\w*|community|communities|developer\s+community)", low, re.I):
        return False

    local_scope = bool(re.search(
        r"(?:\bapril\b|април\w*|/space|\bspace\s+page\b|на\s+сайт\w*|в\s+приложени\w*|"
        r"мой\s+сообществ\w*|мое\s+сообществ\w*|моё\s+сообществ\w*|"
        r"открой|перейд\w*|зайди|войд\w*|найди\s+пользоват|добав\w*\s+друг|"
        r"личн\w*\s+чат|публичн\w*\s+пост|раздел\s+участник\w*|страниц\w*\s+сообществ\w*)",
        low, re.I,
    ))
    if local_scope:
        return False

    external_developer_community = bool(re.search(
        r"(?:сообществ\w*.{0,55}(?:разработчик\w*|программист\w*|open[- ]?source)|"
        r"(?:разработчик\w*|программист\w*|open[- ]?source).{0,55}сообществ\w*)",
        low, re.IGNORECASE,
    ))
    if external_developer_community:
        return True

    global_scope = bool(re.search(
        r"(?:миров\w*|глобальн\w*|международн\w*|worldwide|global|international|"
        r"\b(?:it|ai|ml)\b|айти|искусственн\w*\s+интеллект\w*|\bии\b|нейросет\w*|"
        r"разработчик\w*|исследовател\w*|open[- ]?source|machine\s+learning|генеративн\w*\s+ии)",
        low, re.I,
    ))
    topical_intent = bool(re.search(
        r"(?:что\s+(?:сейчас\s+)?актуальн\w*|актуальн\w*\s+сейчас|что\s+обсужда\w*|"
        r"какие\s+тенденц\w*|нов\w*\s+направлен\w*|что\s+происход\w*|"
        r"тренд\w*|разработк\w*|исследовани\w*|состояни\w*\s+отрасл\w*)",
        low, re.I,
    ))
    # A clear world/global qualifier is sufficient; otherwise require both a
    # technical domain and an informational/trend question.
    explicit_world = bool(re.search(r"(?:миров\w*|глобальн\w*|международн\w*|worldwide|global|international)", low, re.I))
    return explicit_world or (global_scope and topical_intent)

def _semantic_site_area_scores(query: str) -> list[tuple[float, str]]:
    """Rank existing map entries from the request plus their visible UI semantics.

    Phrase/synonym matches are evidence, not required literal commands. The same
    retrieval handles colloquial phrasing such as 'старый разговор', 'прицепить
    документ', or 'поменять ник' and keeps each matching child card distinct.
    """
    q = str(query or "").lower().replace("ё", "е").strip()
    if _is_external_community_topic(q):
        return []
    q_words = _site_words(q)
    if not q_words:
        return []
    concept_ids: set[str] = set()
    for concept_id, phrases in _SITE_CONCEPT_ALIASES.items():
        if any(phrase in q for phrase in phrases):
            concept_ids.add(concept_id)
    # The catalog is a route-specific alias index and executable regression corpus.
    # Exact normalized phrase hits outweigh generic token overlap so "community" never
    # wins over "history" merely because both cards link through the same profile.
    catalog_scores: dict[str, float] = {}
    normalized_q = _normalize_site_catalog_phrase(q)
    matched_cases = APRIL_UI_HELP_QUERY_INDEX.get(normalized_q, [])
    for case in matched_cases:
        area_id = str(case.get("area_id") or "")
        phrase = str(case.get("query") or "")
        if area_id and phrase:
            catalog_scores[area_id] = max(catalog_scores.get(area_id, 0.0), 13.0 + len(phrase) / 500.0)
    scored: list[tuple[float, str]] = []
    for area in APRIL_SITE_MAP.get("areas", []):
        if not isinstance(area, dict):
            continue
        area_id = str(area.get("id") or "")
        if area_id == "admin-support":
            continue
        fields = [area.get("label"), area.get("purpose"), area.get("path"), *area.get("steps", [])]
        for function in APRIL_UI_FUNCTION_CATALOG.get("functions", []):
            if isinstance(function, dict) and area_id in (function.get("areas") or []):
                fields.extend([
                    function.get("screen"), function.get("entry"), function.get("position"),
                    function.get("control"), function.get("does"), *function.get("how_to_use", []),
                ])
        searchable = " ".join(str(item) for item in fields if item)
        a_words = _site_words(searchable)
        intersection = q_words & a_words
        # Normalize common Russian inflections lightly: 'диалогами/диалога',
        # 'профиле/профиля', etc. Do not do fuzzy matching on stop-words.
        stem_hits = sum(1 for qword in q_words if len(qword) >= 4 and any(aword.startswith(qword[:5]) or qword.startswith(aword[:5]) for aword in a_words if len(aword) >= 4))
        score = (len(intersection) * 1.35) + (stem_hits * 0.45)
        if any(str(area.get("label") or "").lower().replace("ё", "е") in q or str(area.get("path") or "").lower() == q for _ in [0]):
            score += 5.0
        if area_id in concept_ids:
            score += 4.0
        score = max(score, catalog_scores.get(area_id, 0.0))
        if any(str(phrase).lower().replace("ё", "е") in q for phrase in _SITE_AREA_HINTS.get(area_id, ())):
            score += 2.0
        if score > 0:
            scored.append((score, area_id))
    scored.sort(key=lambda item: (-item[0], next((i for i, area in enumerate(APRIL_SITE_MAP["areas"]) if area.get("id") == item[1]), 999)))
    return scored

